{"command":"python3 -c '
import json
cmds = []
notes = [ "C-4", "C-5", "D#5", "F-5", "G-5", "A#4" ]
for i, n in enumerate(notes):
    cmds.append({"name":"pattern_set_cell","arguments":{"pattern":0,"row":i*8,"channel":0,"note":n,"instrument":1,"volume":48}})
for i in range(0,64,4):
    cmds.append({"name":"pattern_set_cell","arguments":{"pattern":0,"row":i,"channel":4,"note":"C-6","instrument":4,"volume":20}})
for i in range(0,64,16):
    cmds.append({"name":"pattern_set_cell","arguments":{"pattern":0,"row":i,"channel":5,"note":"C-5","instrument":3,"volume":45}})
for i in range(0,64,8):
    cmds.append({"name":"pattern_set_cell","arguments":{"pattern":0,"row":i,"channel":2,"note":"C-5","instrument":2,"volume":32}})
for i in range(0,64,16):
    cmds.append({"name":"pattern_set_cell","arguments":{"pattern":0,"row":i,"channel":1,"note":"C-3","instrument":1,"volume":55}})
with open("/tmp/final.json","w") as f: json.dump(cmds,f)
print("Final batch with", len(cmds), "commands written")
' 2>&1 | cat"}

